const data = $json.output ?? $json;

const property = data.property || {};
const financials = data.financials || {};
const risks = data.risk_flags || [];
const investment = data.investment_analysis || {};

const requiredRiskCategories = [
  "Rent PSF vs Market",
  "Cap Rate",
  "Clear Height",
  "Vacancy",
  "Price/SF vs Comparable Market Data"
];

const normalize = (value) => String(value || "").toLowerCase().replace(/\s+/g, " ").trim();
const existingRiskNames = risks.map((r) => normalize(r.category));
const missingRiskCategories = requiredRiskCategories.filter((required) => !existingRiskNames.includes(normalize(required)));

const coreFinancialFields = ["purchase_price","price_per_sf","subject_rent_psf","stabilized_noi","cap_rate_percent"];
const financialFieldsPresent = coreFinancialFields.filter((field) => financials[field] !== null && financials[field] !== undefined);

const occupancy = property.occupancy_percent !== null && property.occupancy_percent !== undefined ? Number(property.occupancy_percent) : null;
const buildingSize = property.building_size_sf !== null && property.building_size_sf !== undefined ? Number(property.building_size_sf) : null;
const purchasePrice = financials.purchase_price !== null && financials.purchase_price !== undefined ? Number(financials.purchase_price) : null;
const stabilizedNoi = financials.stabilized_noi !== null && financials.stabilized_noi !== undefined ? Number(financials.stabilized_noi) : null;

const subjectVacancyPercent = occupancy !== null ? Number((100 - occupancy).toFixed(2)) : null;
const calculatedPricePerSf = purchasePrice !== null && buildingSize !== null && buildingSize > 0 ? Number((purchasePrice / buildingSize).toFixed(2)) : null;
const calculatedCapRatePercent = stabilizedNoi !== null && purchasePrice !== null && purchasePrice > 0 ? Number(((stabilizedNoi / purchasePrice) * 100).toFixed(2)) : null;

const rentRisk = risks.find((r) => normalize(r.category) === normalize("Rent PSF vs Market"));
const capRateRisk = risks.find((r) => normalize(r.category) === normalize("Cap Rate"));

const allowedRecommendations = ["BUY","CONSIDER","REVIEW","PASS","INSUFFICIENT_DATA"];

const checks = {
  required_risk_categories_present: missingRiskCategories.length === 0,
  missing_risk_categories: missingRiskCategories,
  financial_fields_present: financialFieldsPresent.length,
  financial_fields_total: coreFinancialFields.length,
  financial_data_complete: financialFieldsPresent.length === coreFinancialFields.length,
  subject_vacancy_percent: subjectVacancyPercent,
  rent_vs_market_evaluable: financials.subject_rent_psf !== null && financials.subject_rent_psf !== undefined,
  cap_rate_calculable: stabilizedNoi !== null && purchasePrice !== null && purchasePrice > 0,
  price_per_sf_calculable: purchasePrice !== null && buildingSize !== null && buildingSize > 0,
  rent_risk_consistent: financials.subject_rent_psf == null ? normalize(rentRisk?.severity) === "not_evaluable" : true,
  cap_rate_risk_consistent: stabilizedNoi == null || purchasePrice == null ? normalize(capRateRisk?.severity) === "not_evaluable" : true,
  recommendation_valid: allowedRecommendations.includes(investment.recommendation)
};

checks.all_critical_checks_passed = checks.required_risk_categories_present && checks.rent_risk_consistent && checks.cap_rate_risk_consistent && checks.recommendation_valid;

const calculatedMetrics = {
  subject_vacancy_percent: subjectVacancyPercent,
  price_per_sf: calculatedPricePerSf,
  price_per_sf_calculated: calculatedPricePerSf !== null,
  cap_rate_percent: calculatedCapRatePercent,
  cap_rate_calculated: calculatedCapRatePercent !== null
};

return { output: { ...data, calculated_metrics: calculatedMetrics, deterministic_validation: checks } };
